void DataEditor::edit(const std::function<void(Project &)> &fn){auto p=project;fn(p);editing=true;if(onEdit)onEdit(p);else setProject(p);editing=false;}
void DataEditor::setProject(const Project &p){project=p;populate();errors->setText(p.validateSystems().mid(0,4).join('\n'));if(!editing)inspect();}
void DataEditor::populate(){QSignalBlocker block(tree);bool first=tree->topLevelItemCount()==0;QSet<QString> expanded;for(QTreeWidgetItemIterator it(tree);*it;++it)if((*it)->isExpanded())expanded.insert((*it)->data(0,Qt::UserRole).toString());QTreeWidgetItem *chosen=nullptr;tree->clear();auto node=[&](QTreeWidgetItem *parent,QString title,QString key){auto *n=parent?new QTreeWidgetItem(parent):new QTreeWidgetItem(tree);n->setText(0,title);n->setData(0,Qt::UserRole,key);n->setExpanded(first||expanded.contains(key));if(key==selected)chosen=n;return n;};auto *root=node(nullptr,project.title,"project");auto worlds=project.allAreas();for(int s=0;s<project.scenes.size();++s){auto *scene=node(root,project.scenes[s].name,"scene:"+QString::number(s));for(int m=0;m<project.maps.size();++m)if(project.maps[m].scene==project.scenes[s].id){auto *map=node(scene,project.maps[m].name,"map:"+QString::number(m));for(int w=0;w<worlds.size();++w)if(worlds[w].mapId==project.maps[m].id){auto *area=node(map,worlds[w].name,"area:"+QString::number(w));for(int i=0;i<worlds[w].objects.size();++i)node(area,"▣ "+worlds[w].objects[i].name,QString("object:%1:%2").arg(w).arg(i));for(int i=0;i<worlds[w].actors.size();++i)node(area,"♟ "+worlds[w].actors[i].name,QString("actor:%1:%2").arg(w).arg(i));}}}
auto library=[&](QString title,QString kind,auto values){auto *group=node(root,title,kind);for(int i=0;i<values.size();++i){QString name;if constexpr(std::is_same_v<std::decay_t<decltype(values[i])>,Variable>)name=values[i].id;else name=values[i].name;node(group,name,kind+":"+QString::number(i));}};library("Variables","variable",project.variables);library("Items","item",project.items);library("Storage","storage",project.storages);library("Scripts","script",project.scripts);library("Timers","timer",project.timers);library("NPC library","npc",project.npcs);if(!chosen){selected="project";chosen=root;}tree->setCurrentItem(chosen);for(auto *parent=chosen->parent();parent;parent=parent->parent())parent->setExpanded(true);}
